// Aggregateノードから来た配列データを個別の記事アイテムに変換
const items = [];
const titles = $input.item.json.title || [];
const sources = $input.item.json.source || [];
const pubDates = $input.item.json.pubDate || [];
const links = $input.item.json.link || [];
const contents = $input.item.json.content || [];

for (let i = 0; i < titles.length; i++) {
  items.push({
    json: {
      article_index: i + 1,
      title: titles[i] || '',
      source: sources[i] || '',
      pubDate: pubDates[i] || '',
      link: links[i] || '',
      content: contents[i] || '',
      content_length: (contents[i] || '').length,
      execution_date: new Date().toISOString().replace('T', ' ').substr(0, 19)
    }
  });
}

return items;
